<?php
declare(strict_types=1);namespace App\Controllers\Admin;
use App\Core\Controller;use App\Core\Database;use PDO;
class FaqController extends Controller{
 public function index():void{$pdo=Database::connection();$_SESSION['csrf_token']??=bin2hex(random_bytes(32));if($_SERVER['REQUEST_METHOD']==='POST')$this->post($pdo);$faqs=$pdo->query('SELECT * FROM faqs ORDER BY sort_order,id')->fetchAll();$edit=null;$id=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('SELECT * FROM faqs WHERE id=?');$s->execute([$id]);$edit=$s->fetch()?:null;}$flash=$_SESSION['faq_flash']??null;unset($_SESSION['faq_flash']);$this->view('layouts/admin-layout',['title'=>'FAQs','showPageTitle'=>false,'content'=>$this->render('admin/faqs/index',compact('faqs','edit','flash')+['csrfToken'=>$_SESSION['csrf_token']])]);}
 private function post(PDO $pdo):never{if(!hash_equals((string)($_SESSION['csrf_token']??''),(string)($_POST['csrf_token']??''))){http_response_code(419);exit('Invalid request token.');}$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:null;if(($_POST['action']??'save')==='delete'&&$id){$pdo->prepare('DELETE FROM faqs WHERE id=?')->execute([$id]);$this->go('FAQ deleted.');}$q=trim((string)($_POST['question']??''));$a=trim((string)($_POST['answer']??''));if($q===''||$a==='')$this->go('Question and answer are required.','error',$id);$data=[$q,$a,trim((string)($_POST['category']??'')),max(0,(int)($_POST['sort_order']??0)),isset($_POST['status'])?'active':'inactive'];if($id)$pdo->prepare('UPDATE faqs SET question=?,answer=?,category=?,sort_order=?,status=? WHERE id=?')->execute([...$data,$id]);else$pdo->prepare('INSERT INTO faqs(question,answer,category,sort_order,status) VALUES(?,?,?,?,?)')->execute($data);$this->go('FAQ saved.');}
 private function go(string $message,string $type='success',?int $id=null):never{$_SESSION['faq_flash']=compact('message','type');header('Location: /admin/faqs'.($id?'?edit='.$id:''),true,303);exit;}
}
